<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<meta name="theme-color" content="#0b0e13">
<title>Bounce Lab</title>
<style>
  :root{
    --bg:#0b0e13; --panel:#0d1119; --line:#20262f;
    --text:#e9edf3; --muted:#8b94a5;
    --teal:#5eead4; --violet:#a78bfa;
  }
  *{box-sizing:border-box;margin:0;padding:0}
  body{
    min-height:100vh;padding:28px 20px;
    display:flex;align-items:center;justify-content:center;
    background:
      radial-gradient(1100px 620px at 72% -12%, rgba(167,139,250,.09), transparent 62%),
      radial-gradient(900px 520px at 12% 112%, rgba(94,234,212,.07), transparent 60%),
      var(--bg);
    color:var(--text);
    font-family:"Segoe UI",system-ui,-apple-system,"Helvetica Neue",sans-serif;
  }
  .wrap{width:min(720px,100%)}
  header{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin-bottom:14px}
  h1{font-size:21px;font-weight:650;letter-spacing:-.01em;display:flex;align-items:center;gap:9px}
  .hint{color:var(--muted);font-size:12.5px}
  .stage{
    border:1px solid var(--line);border-radius:14px;overflow:hidden;
    background:var(--panel);
    box-shadow:0 34px 90px -34px rgba(0,0,0,.85), inset 0 1px 0 rgba(255,255,255,.04);
  }
  canvas{display:block;width:100%;min-width:400px;height:auto;cursor:crosshair;touch-action:none}
  .bar{display:flex;align-items:center;gap:10px;margin-top:14px;flex-wrap:wrap}
  button{
    appearance:none;border:1px solid var(--line);background:#131826;color:var(--text);
    padding:9px 17px;border-radius:9px;font-size:13.5px;font-weight:600;cursor:pointer;
    display:inline-flex;align-items:center;gap:8px;user-select:none;font-family:inherit;
    transition:border-color .15s,background .15s,transform .1s,color .15s;
  }
  button:hover{border-color:#303a4c;background:#182031;transform:translateY(-1px)}
  button:active{transform:translateY(0)}
  .dot{width:7px;height:7px;border-radius:50%;background:currentColor;opacity:.9}
  #drop{border-color:rgba(167,139,250,.45)}
  #drop:hover{border-color:var(--violet)}
  #play{min-width:98px}
  #play.on{border-color:rgba(94,234,212,.5);color:var(--teal)}
  #clear:hover{border-color:rgba(248,113,113,.55);color:#fca5a5}
  .stats{margin-left:auto;color:var(--muted);font-size:12px;font-variant-numeric:tabular-nums;white-space:nowrap}
</style>
</head>
<body>
<div class="wrap">
  <header>
    <h1>
      <svg width="20" height="20" viewBox="0 0 20 20" aria-hidden="true">
        <defs>
          <radialGradient id="lg" cx="35%" cy="30%" r="80%">
            <stop offset="0%" stop-color="#b7f4e6"/>
            <stop offset="100%" stop-color="#0ea5a0"/>
          </radialGradient>
        </defs>
        <circle cx="10" cy="10" r="8.2" fill="url(#lg)"/>
      </svg>
      Bounce&nbsp;Lab
    </h1>
    <span class="hint">click the canvas to drop a ball</span>
  </header>

  <div class="stage"><canvas id="sim" width="680" height="440"></canvas></div>

  <div class="bar">
    <button id="drop" title="Add a ball from the top (D)"><span class="dot"></span>Drop ball</button>
    <button id="play" class="on" title="Toggle animation (Space)"><span class="dot"></span><span id="playLabel">Pause</span></button>
    <button id="clear" title="Remove all balls (C)">Clear</button>
    <span class="stats" id="stats"></span>
  </div>
</div>

<script>
(() => {
"use strict";
const TAU = Math.PI * 2;
const W = 680, H = 440;
const G = 0.55;            // gravity per step^2
const REST = 0.84;         // floor restitution (< 1)
const REST_WALL = 0.87;    // wall restitution (< 1)
const MAX_BALLS = 160;
const PAL = [172, 203, 262, 292, 328, 40, 92];

const canvas = document.getElementById("sim");
const statsEl = document.getElementById("stats");
const playBtn = document.getElementById("play");
const playLabel = document.getElementById("playLabel");
const dpr = Math.min(window.devicePixelRatio || 1, 2);
canvas.width = W * dpr;
canvas.height = H * dpr;
const ctx = canvas.getContext("2d");
ctx.scale(dpr, dpr);

/* dotted backdrop, prerendered once */
const grid = document.createElement("canvas");
grid.width = W * dpr; grid.height = H * dpr;
{
  const g = grid.getContext("2d");
  g.scale(dpr, dpr);
  g.fillStyle = "rgba(148,163,184,0.085)";
  for (let x = 22; x < W; x += 28)
    for (let y = 22; y < H; y += 28) {
      g.beginPath(); g.arc(x, y, 1, 0, TAU); g.fill();
    }
}

const balls = [];
const pulses = [];
let hueIdx = (Math.random() * PAL.length) | 0;
let playing = true;

const num = v => { v = Number(v); return Number.isFinite(v) ? v : 0; };
const rand = (a, b) => a + Math.random() * (b - a);

/* ---------- tiny synth for bounce ticks ---------- */
let actx = null, lastBlip = 0;
function initAudio() {
  if (!actx) {
    try { actx = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) {}
  }
  if (actx && actx.state === "suspended") actx.resume();
}
function tick(impact, r, wall) {
  if (!actx || actx.state !== "running") return;
  const now = performance.now();
  if (now - lastBlip < 45) return;
  lastBlip = now;
  const f = Math.max(130, (wall ? 430 : 310) + (22 - r) * 7 + rand(-18, 18));
  const o = actx.createOscillator(), gn = actx.createGain();
  o.type = "sine";
  o.frequency.setValueAtTime(f, actx.currentTime);
  o.frequency.exponentialRampToValueAtTime(f * 0.55, actx.currentTime + 0.09);
  gn.gain.setValueAtTime(Math.min(0.085, 0.012 + impact * 0.005), actx.currentTime);
  gn.gain.exponentialRampToValueAtTime(0.0001, actx.currentTime + 0.11);
  o.connect(gn).connect(actx.destination);
  o.start(); o.stop(actx.currentTime + 0.12);
}

/* ---------- physics ---------- */
function hit(b, impact, wall) {
  b.squashAxis = wall ? "x" : "y";
  b.squash = Math.max(b.squash, Math.min(1, impact / 13));
  tick(impact, b.r, wall);
}

function physicsStep(dt) {
  for (let i = balls.length - 1; i >= 0; i--) {
    const b = balls[i];
    b.vy += G * dt;                        // gravity accelerates downward
    const ivx = b.vx, ivy = b.vy;          // pre-collision speeds (for juice)
    b.x += b.vx * dt;
    b.y += b.vy * dt;

    if (b.y + b.r > H) {                   // floor: clamp + reverse vy
      b.y = H - b.r;
      if (b.vy > 0) {
        const sp = b.vy * REST;
        b.vy = sp < 0.5 ? 0 : -sp;         // energy loss, settles when tiny
        b.vx *= 0.985;                     // whisper of floor friction
      }
      if (ivy > 2.2) hit(b, ivy, false);
    } else if (b.y - b.r < 0) {            // ceiling
      b.y = b.r;
      if (b.vy < 0) {
        const sp = -b.vy * REST_WALL;
        b.vy = sp < 0.5 ? 0 : sp;
      }
      if (-ivy > 2.2) hit(b, -ivy, false);
    }

    if (b.x + b.r > W) {                   // right wall: clamp + reverse vx
      b.x = W - b.r;
      if (b.vx > 0) b.vx = -b.vx * REST_WALL;
      if (ivx > 2.2) hit(b, ivx, true);
    } else if (b.x - b.r < 0) {            // left wall
      b.x = b.r;
      if (b.vx < 0) b.vx = -b.vx * REST_WALL;
      if (-ivx > 2.2) hit(b, -ivx, true);
    }

    b.squash *= Math.pow(0.86, dt);
    if (b.squash < 0.01) b.squash = 0;
    b.age += dt;
    b.tt += dt;
    if (b.tt >= 2) {
      b.tt = 0;
      b.trail.push({ x: b.x, y: b.y });
      if (b.trail.length > 8) b.trail.shift();
    }
  }
  for (let i = pulses.length - 1; i >= 0; i--) {
    pulses[i].t += dt / 14;
    if (pulses[i].t >= 1) pulses.splice(i, 1);
  }
}

/* ---------- rendering ---------- */
const easeOut = t => 1 - Math.pow(1 - t, 3);

function draw() {
  ctx.clearRect(0, 0, W, H);
  ctx.drawImage(grid, 0, 0, W, H);

  for (const p of pulses) {
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.r0 + easeOut(p.t) * 44, 0, TAU);
    ctx.strokeStyle = `hsla(${p.hue},90%,72%,${0.4 * (1 - p.t)})`;
    ctx.lineWidth = 2.2 * (1 - p.t) + 0.4;
    ctx.stroke();
  }

  for (const b of balls) {
    for (let i = 0; i < b.trail.length; i++) {
      const tr = b.trail[i], k = (i + 1) / b.trail.length;
      ctx.beginPath();
      ctx.arc(tr.x, tr.y, b.r * (0.35 + 0.5 * k), 0, TAU);
      ctx.fillStyle = `hsla(${b.hue},90%,66%,${0.14 * k})`;
      ctx.fill();
    }

    const s = b.squash;
    let sx = 1, sy = 1;
    if (s > 0) {
      if (b.squashAxis === "y") { sy = 1 - 0.32 * s; sx = 1 + 0.32 * s; }
      else                      { sx = 1 - 0.32 * s; sy = 1 + 0.32 * s; }
    }
    const R = b.r * easeOut(Math.min(1, b.age / 9));   // pop-in on spawn

    ctx.save();
    ctx.translate(b.x, b.y);
    ctx.scale(sx, sy);
    const grad = ctx.createRadialGradient(-R * 0.35, -R * 0.4, R * 0.12, 0, 0, R);
    grad.addColorStop(0, `hsl(${b.hue},96%,79%)`);
    grad.addColorStop(0.55, `hsl(${b.hue},86%,58%)`);
    grad.addColorStop(1, `hsl(${b.hue},82%,41%)`);
    ctx.shadowColor = `hsla(${b.hue},92%,62%,0.55)`;
    ctx.shadowBlur = 14;
    ctx.fillStyle = grad;
    ctx.beginPath(); ctx.arc(0, 0, R, 0, TAU); ctx.fill();
    ctx.shadowBlur = 0;
    ctx.beginPath();
    ctx.arc(-R * 0.33, -R * 0.37, R * 0.2, 0, TAU);
    ctx.fillStyle = "rgba(255,255,255,0.72)";
    ctx.fill();
    ctx.restore();
  }
}

let statsCache = "";
function updateStats() {
  const t = `${balls.length} ball${balls.length === 1 ? "" : "s"} · ${playing ? "live" : "paused"}`;
  if (t !== statsCache) { statsCache = t; statsEl.textContent = t; }
}

/* ---------- public API ---------- */
function addBall(x, y, vx = 0, vy = 0, r) {
  x = num(x); y = num(y); vx = num(vx); vy = num(vy);
  r = (r == null) ? rand(9, 16) : num(r);
  r = Math.max(3, Math.min(r, 80));
  x = Math.min(Math.max(x, r), W - r);     // born inside the canvas, always
  y = Math.min(Math.max(y, r), H - r);
  hueIdx = (hueIdx + 1) % PAL.length;
  const b = { x, y, vx, vy, r, hue: PAL[hueIdx], age: 0, squash: 0, squashAxis: "y", trail: [], tt: 0 };
  balls.push(b);
  if (balls.length > MAX_BALLS) balls.shift();
  pulses.push({ x, y, r0: r, t: 0, hue: b.hue });
  if (pulses.length > 40) pulses.shift();
  updateStats();
  return b;
}

function clear() {
  balls.length = 0;
  updateStats();
}

function step(dt = 1) {
  dt = num(dt);
  if (!(dt > 0)) dt = 1;
  if (dt > 12) dt = 12;
  let rem = dt;
  while (rem > 1e-9) {                     // sub-steps keep fast balls colliding cleanly
    const h = Math.min(rem, 0.5);
    physicsStep(h);
    rem -= h;
  }
  draw();
  updateStats();
}

window.sim = {
  w: W,
  h: H,
  balls: () => balls.map(b => ({ x: b.x, y: b.y, vx: b.vx, vy: b.vy, r: b.r })),
  addBall,
  clear,
  step
};

/* ---------- UI wiring ---------- */
document.getElementById("drop").addEventListener("click", () => {
  addBall(rand(50, W - 50), rand(30, 140), rand(-3.5, 3.5), rand(0, 2));
});

playBtn.addEventListener("click", () => {
  playing = !playing;
  playBtn.classList.toggle("on", playing);
  playLabel.textContent = playing ? "Pause" : "Play";
  updateStats();
});

document.getElementById("clear").addEventListener("click", clear);

canvas.addEventListener("pointerdown", e => {
  const rect = canvas.getBoundingClientRect();
  addBall(
    (e.clientX - rect.left) * (W / rect.width),
    (e.clientY - rect.top) * (H / rect.height),
    rand(-2.5, 2.5), rand(-1, 1)
  );
});

document.addEventListener("pointerdown", initAudio);

window.addEventListener("keydown", e => {
  if (e.target !== document.body) return;
  if (e.code === "Space") { e.preventDefault(); playBtn.click(); }
  else if (e.key === "d" || e.key === "D") document.getElementById("drop").click();
  else if (e.key === "c" || e.key === "C") clear();
});

/* ---------- main loop ---------- */
let last = performance.now();
function frame(now) {
  requestAnimationFrame(frame);
  const el = Math.min(now - last, 100);
  last = now;
  if (!playing) return;
  let rem = el / (1000 / 60);
  while (rem > 1e-9) {
    const h = Math.min(rem, 0.5);
    physicsStep(h);
    rem -= h;
  }
  draw();
  updateStats();
}

/* opening scene */
for (let i = 0; i < 6; i++) {
  addBall(rand(60, W - 60), rand(40, H * 0.5), rand(-4, 4), rand(-2, 2));
}
updateStats();
requestAnimationFrame(frame);
})();
</script>
</body>
</html>
